	"strings"
)

var reader *bufio.Reader
var inputStrings []string
var currentLine int

func main() {
	reader = bufio.NewReader(os.Stdin)
	inputBytes := make([]byte, 0)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			break
		}
		inputBytes = append(inputBytes, b)
	}
	inputStr := strings.TrimSpace(string(inputBytes))
	inputStrings = strings.Split(inputStr, "\n")
	for i := range inputStrings {
		inputStrings[i] = strings.TrimSpace(inputStrings[i])
	}
	currentLine = 0
	mainFunc()
}

func readline() string {
	line := inputStrings[currentLine]
	currentLine++
	return line
}

func output(x interface{}) {
	fmt.Println(x)
}

func mainFunc() {
	N := parseInt(readline())
	for test := 0; test < N; test++ {
		f := splitAndParse(readline())
		s := splitAndParse(readline())
		result := 2
		if f[0] == 0 && f[1] == 0 && s[0] == 0 && s[1] == 0 {
			result = 0
		} else if f[0]+f[1]+s[0]+s[1] == 4 {
			result = 2
		} else {
			result = 1
		}
		output(result)
	}
}

func parseInt(s string) int {
	var n int
	fmt.Sscanf(s, "%d", &n)
	return n
}

func splitAndParse(s string) []int {
	parts := strings.Split(s, " ")
	result := make([]int, len(parts))
	for i, p := range parts {
		result[i] = parseInt(p)
	}
	return result
}
